<div class="card admin-card mb-4"><div class="card-header bg-white py-3"><h2 class="h5 mb-0">3. Images</h2></div><div class="card-body"><div class="row g-3 mb-4"><div class="col-md-7"><label class="form-label" for="cover_image">Cover image</label><input class="form-control" type="file" id="cover_image" name="cover_image" accept="image/jpeg,image/png,image/webp">@if($experience?->cover_image)<div class="form-check mt-2"><input type="hidden" name="remove_cover_image" value="0"><input class="form-check-input" type="checkbox" name="remove_cover_image" value="1" id="remove_experience_cover"><label class="form-check-label text-danger" for="remove_experience_cover">Remove cover image</label></div>@endif</div><div class="col-md-5"><x-admin.image-preview id="experience-cover-preview" :src="$experience?->cover_image ? Storage::disk('public')->url($experience->cover_image) : null" alt="Experience cover preview" /></div></div><div class="d-flex justify-content-between mb-3"><h3 class="h6">Gallery images</h3><button type="button" class="btn btn-sm btn-outline-success" data-repeater-add="experience-gallery" data-template="experience-gallery-template">Add image</button></div><div id="experience-gallery" data-next-index="{{ $experience?->images->count()??0 }}">@foreach($experience?->images??[] as $index=>$image)<div class="border rounded p-3 mb-3" data-repeater-row><input type="hidden" name="gallery[{{ $index }}][id]" value="{{ $image->id }}"><div class="row g-3"><div class="col-md-2"><img class="rounded object-fit-cover w-100" src="{{ Storage::disk('public')->url($image->image_path) }}" alt="{{ $image->alt_text }}" height="90"></div><div class="col-md-3"><label class="form-label">Replace image</label><input class="form-control" type="file" name="gallery[{{ $index }}][image]" accept="image/jpeg,image/png,image/webp"></div><div class="col-md-2"><label class="form-label">Alt text</label><input class="form-control" name="gallery[{{ $index }}][alt_text]" value="{{ $image->alt_text }}"></div><div class="col-md-2"><label class="form-label">Caption</label><input class="form-control" name="gallery[{{ $index }}][caption]" value="{{ $image->caption }}"></div><div class="col-md-1"><label class="form-label">Order</label><input class="form-control" type="number" min="0" name="gallery[{{ $index }}][display_order]" value="{{ $image->display_order }}"></div><div class="col-md-2 form-check align-self-end mb-2"><input class="form-check-input" type="checkbox" name="gallery[{{ $index }}][_remove]" value="1" id="remove-experience-image-{{ $image->id }}"><label class="form-check-label text-danger" for="remove-experience-image-{{ $image->id }}">Remove</label></div></div></div>@endforeach</div><p class="small text-muted">Use display order to reorder images. JPEG, PNG or WebP up to 5 MB.</p></div></div>
<template id="experience-gallery-template"><div class="border rounded p-3 mb-3" data-repeater-row><div class="row g-3"><div class="col-md-4"><label class="form-label">Image</label><input class="form-control" type="file" name="gallery[__INDEX__][image]" accept="image/jpeg,image/png,image/webp" required></div><div class="col-md-3"><label class="form-label">Alt text</label><input class="form-control" name="gallery[__INDEX__][alt_text]"></div><div class="col-md-3"><label class="form-label">Caption</label><input class="form-control" name="gallery[__INDEX__][caption]"></div><div class="col-md-1"><label class="form-label">Order</label><input class="form-control" type="number" min="0" name="gallery[__INDEX__][display_order]" value="0"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-outline-danger" type="button" data-remove-new-row>×</button></div></div></div></template>
